-- Post-visit review requests (S55.2, ADR-0059): where the business wants its reviews (NULL: no
-- requests are drafted), and `message.review_request` on the dial.
ALTER TABLE "ai_action_executions" DROP CONSTRAINT "ai_action_executions_action_known";--> statement-breakpoint
ALTER TABLE "ai_action_proposals" DROP CONSTRAINT "ai_action_proposals_action_known";--> statement-breakpoint
ALTER TABLE "autonomy_settings" DROP CONSTRAINT "autonomy_settings_levels_known";--> statement-breakpoint
ALTER TABLE "tenants" ADD COLUMN "review_url" text;--> statement-breakpoint
ALTER TABLE "ai_action_executions" ADD CONSTRAINT "ai_action_executions_action_known" CHECK ("ai_action_executions"."action" IN ('booking.create', 'booking.move', 'booking.cancel', 'booking_request.accept', 'time.block', 'client_note.save', 'rule.change', 'task.create', 'waitlist.change', 'message.confirmation', 'message.rebooking_nudge', 'message.waitlist_offer', 'message.bulk', 'message.review_request'));--> statement-breakpoint
ALTER TABLE "ai_action_proposals" ADD CONSTRAINT "ai_action_proposals_action_known" CHECK ("ai_action_proposals"."action" IN ('booking.create', 'booking.move', 'booking.cancel', 'booking_request.accept', 'time.block', 'client_note.save', 'rule.change', 'task.create', 'waitlist.change', 'message.confirmation', 'message.rebooking_nudge', 'message.waitlist_offer', 'message.bulk', 'message.review_request'));--> statement-breakpoint
ALTER TABLE "autonomy_settings" ADD CONSTRAINT "autonomy_settings_levels_known" CHECK (jsonb_typeof("autonomy_settings"."levels") = 'object' AND "autonomy_settings"."levels" - ARRAY['booking.create', 'booking.move', 'booking.cancel', 'booking_request.accept', 'time.block', 'client_note.save', 'rule.change', 'task.create', 'waitlist.change', 'message.confirmation', 'message.rebooking_nudge', 'message.waitlist_offer', 'message.bulk', 'message.review_request'] = '{}'::jsonb AND NOT jsonb_path_exists("autonomy_settings"."levels", '$.* ? (@ != "ask" && @ != "notify" && @ != "auto")'));--> statement-breakpoint
ALTER TABLE "tenants" ADD CONSTRAINT "tenants_review_url_format" CHECK (length("tenants"."review_url") <= 500 AND "tenants"."review_url" ~ '^https://[^[:space:]]+$');